export const curriculumBlueprintBySkill = Object.fromEntries(
  skillCurriculumBlueprints.map(entry => [entry.skillId, entry])
) as Record<SkillId, SkillCurriculumBlueprint>;

export function curriculumTopicId(skillId: SkillId, slug: string) {
  return `${skillId}:topic:${slug}` as const;
}

export function curriculumSubtopicId(skillId: SkillId, slug: string) {
  return `${skillId}:subtopic:${slug}` as const;
}

export function curriculumLessonId(skillId: SkillId, slug: string) {
  return `${skillId}:lesson:${slug}` as const;
}

export function topicIdsForResource(resourceId: string) {
  return skillCurriculumBlueprints.flatMap(skill => skill.topics
    .filter(entry => entry.resourceIds.includes(resourceId))
    .map(entry => curriculumTopicId(skill.skillId, entry.slug)));
}
